(async()=>{const A=((window.XM_CONFIG&&window.XM_CONFIG.api)||(location.origin+'/tree/api')).replace(/\/+$/,''),c=window.XM_CONFIG||{},id=(c.quiz&&c.quiz.id)||(location.search.match(/[?&]id=([A-Za-z0-9]+)/)||[])[1],rid=n=>[...crypto.getRandomValues(new Uint8Array(n))].map(b=>'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'[b%62]).join(''),r=await(await fetch(A+'/quizzes/'+id+'/round?locale=cn',{headers:{Accept:'application/json'},credentials:'same-origin'})).json(),answers=(r.questions||[]).map(q=>{const o=q.options.find(x=>x.correct);return o?o.index:0}),nm=((prompt('榜上名字（≤15字）','满分选手')||'满分选手').trim().slice(0,15))||'满分选手',tok=await(await fetch(A+'/token',{headers:{Accept:'application/json'},credentials:'same-origin',cache:'no-store'})).json(),res=await fetch(A+'/quizzes/'+id+'/players',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':tok.token},body:JSON.stringify({playerName:nm,answers:answers,submissionId:rid(24)})}),j=await res.json();console.log(j);if(!j.success){alert('提交失败：'+(j.message||res.status));return}localStorage.setItem('XM_tree_played_'+id,JSON.stringify({id:j.player.id,name:nm,score:j.player.score,ending:j.player.ending,perfect:j.player.perfect,key:j.playerKey||null,top:!!j.player.top}));localStorage.removeItem('XM_tree_pending');location.reload()})();

